INS_LIFE: bool = False
INS_HEALTH: bool = False
INS_AUTO: bool = False
INS_HOME: bool = False
INS_UMBRELLA: bool = False

def calculate_premiums_C2(insurance_master: Any, ws_not_eof: bool, ws_eof: bool, ins_coverage_amount: Decimal, ws_life_rate_per_1000: Decimal, ws_health_base_premium: Decimal, ws_auto_base_premium: Decimal, ws_home_rate_per_1000: Decimal, ws_umbrella_rate: Decimal, ins_premium_amount: Decimal, ws_total_premiums: Decimal) -> None:
    """Calculates insurance premiums."""
    print("CALCULATING PREMIUMS...")
    ws_not_eof = True
    while not ws_eof:
        record = insurance_master.read_next()
        if record is None:
            ws_eof = True
        else:
            ws_eof = False
            ws_calc_amount = determine_base_premium_C2(ins_coverage_amount, ws_life_rate_per_1000, ws_health_base_premium, ws_auto_base_premium, ws_home_rate_per_1000, ws_umbrella_rate)
            ws_calc_amount = apply_risk_factor_C2(ws_calc_amount, insurance_master.ins_claims_count)
            ins_premium_amount, ws_total_premiums = calculate_final_premium_C2(ws_calc_amount, ins_premium_amount, ws_total_premiums)

def determine_base_premium_C2(ins_coverage_amount: Decimal, ws_life_rate_per_1000: Decimal, ws_health_base_premium: Decimal, ws_auto_base_premium: Decimal, ws_home_rate_per_1000: Decimal, ws_umbrella_rate: Decimal) -> Decimal:
    """Determines the base premium based on insurance type."""
    ws_calc_amount: Decimal
    if INS_LIFE:
        ws_calc_amount = ins_coverage_amount / 1000 * ws_life_rate_per_1000
    elif INS_HEALTH:
        ws_calc_amount = ws_health_base_premium
    elif INS_AUTO:
        ws_calc_amount = ws_auto_base_premium
    elif INS_HOME:
        ws_calc_amount = ins_coverage_amount / 1000 * ws_home_rate_per_1000
    elif INS_UMBRELLA:
        ws_calc_amount = ws_umbrella_rate
    else:
        ws_calc_amount = Decimal('0.00')
    return ws_calc_amount

def apply_risk_factor_C2(ws_calc_amount: Decimal, ins_claims_count: int) -> Decimal:
    """Applies a risk factor to the calculated amount if claims count is high."""
    if ins_claims_count > 2:
        ws_calc_amount = ws_calc_amount * Decimal('1.25')
    return ws_calc_amount

def calculate_final_premium_C2(ws_calc_amount: Decimal, ins_premium_amount: Decimal, ws_total_premiums: Decimal) -> tuple[Decimal, Decimal]:
    """Calculates the final premium and updates total premiums."""
    ins_premium_amount = ws_calc_amount
    ws_total_premiums += ws_calc_amount
    return ins_premium_amount, ws_total_premiums

