def calculate_portfolio_value_C2(investment_master: Any, ws_not_eof: bool, ws_eof: bool, ws_total_investments: Decimal) -> None:
    """Calculates the portfolio value."""
    print("CALCULATING PORTFOLIO VALUES...")
    ws_not_eof = True
    while not ws_eof:
        record = investment_master.read_next()
        if record is None:
            ws_eof = True
        else:
            ws_eof = False
            inv_market_value = calculate_position_value_C2(investment_master.inv_quantity, investment_master.inv_current_price)
            inv_gain_loss = calculate_gain_loss_C2(inv_market_value, investment_master.inv_quantity, investment_master.inv_purchase_price)
            ws_total_investments = update_totals_C2(inv_market_value, ws_total_investments)

def calculate_position_value_C2(inv_quantity: Decimal, inv_current_price: Decimal) -> Decimal:
    """Calculates the position value."""
    inv_market_value: Decimal
    inv_market_value = inv_quantity * inv_current_price
    return inv_market_value

def calculate_gain_loss_C2(inv_market_value: Decimal, inv_quantity: Decimal, inv_purchase_price: Decimal) -> Decimal:
    """Calculates the gain or loss."""
    inv_gain_loss: Decimal
    inv_gain_loss = inv_market_value - (inv_quantity * inv_purchase_price)
    return inv_gain_loss

def update_totals_C2(inv_market_value: Decimal, ws_total_investments: Decimal) -> Decimal:
    """Updates the total investments."""
    ws_total_investments += inv_market_value
    return ws_total_investments

