def calculate_risk_score_C2(cust_credit_score: int, cust_total_loans: Decimal, cust_total_balance: Decimal, cust_risk_rating: str) -> str:
    """Calculates a risk score based on customer data."""
    ws_calc_result: int = 0
    if cust_credit_score < 600:
        ws_calc_result += 30
    if cust_total_loans > cust_total_balance:
        ws_calc_result += 20
    cust_risk_rating = update_customer_profile_C2(ws_calc_result, cust_risk_rating)
    return cust_risk_rating

def update_customer_profile_C2(ws_calc_result: int, cust_risk_rating: str) -> str:
    """Updates the customer profile based on the calculated risk score."""
    if ws_calc_result > 50:
        cust_risk_rating = 'H'
    elif ws_calc_result > 25:
        cust_risk_rating = 'M'
    else:
        cust_risk_rating = 'L'
    return cust_risk_rating

