def calculate_rewards_C2(tran_amount: Decimal, ws_total_fees: Decimal) -> Decimal:
    """Calculates rewards points."""
    print("CALCULATING REWARDS POINTS...")
    ws_calc_result: Decimal
    ws_calc_result = tran_amount * Decimal('0.01')
    ws_total_fees += ws_calc_result
    return ws_total_fees

def apply_interest_C2(acct_balance: Decimal, ws_credit_card_rate: Decimal) -> Decimal:
    """Applies credit card interest."""
    print("APPLYING CREDIT CARD INTEREST...")
    ws_calc_interest: Decimal
    ws_calc_interest = acct_balance * ws_credit_card_rate / 12
    acct_balance += ws_calc_interest
    return acct_balance

