def portfolio_analysis_C2(investment_master: Any, ws_not_eof: bool, ws_eof: bool, ws_temp_flag: str) -> None:
    """Analyzes portfolios."""
    print("ANALYZING PORTFOLIOS...")
    ws_not_eof = True
    while not ws_eof:
        record = investment_master.read_next()
        if record is None:
            ws_eof = True
        else:
            ws_eof = False
            calculate_returns_C2(investment_master.inv_current_price, investment_master.inv_purchase_price)
            ws_temp_flag = assess_risk_inv_C2(investment_master, ws_temp_flag)
            benchmark_comparison_C2()

def calculate_returns_C2(inv_current_price: Decimal, inv_purchase_price: Decimal) -> None:
    """Calculates investment returns."""
    ws_calc_result: Decimal
    if inv_purchase_price > 0:
        ws_calc_result = (inv_current_price - inv_purchase_price) / inv_purchase_price * 100

def assess_risk_inv_C2(inv: Any, ws_temp_flag: str) -> str:
    """Assess investment risk."""
    if inv.inv_stocks:
        ws_temp_flag = 'H'
    elif inv.inv_bonds:
        ws_temp_flag = 'L'
    elif inv.inv_mutual_fund:
        ws_temp_flag = 'M'
    else:
        ws_temp_flag = 'M'
    return ws_temp_flag

