def main_loop_C5(ws_not_eof: bool, ws_eof: bool, ws_cust_count: int, customer_master: CustomerRecordC5, ws_current_date: str, cust_last_activity: str) -> None:
    """Main loop to process customer records."""
    while ws_not_eof and not ws_eof:
        try:
            customer_master = read_customer_master_next_C5(customer_master)
        except EOFError:
            ws_eof = True
        else:
            i110_update_profile_C5(ws_current_date, cust_last_activity)
            i120_enrich_profile_C5()
            ws_cust_count += 1

