    if txn_type == 'D':
        process_deposit_2300_C5(txn_amount, acct_balance, acct_last_update, audit_entry, audit_account, audit_amount, audit_type, ws_job_id, ws_account_balance, ws_txn_desc, ws_total_deposits, ws_deposit_count)
