def calculate_pmi_C7(ws_ltv_ratio: float, ws_loan_amount: Decimal) -> Decimal:
    """Calculates PMI amount."""
    if ws_ltv_ratio > 95:
        ws_pmi_amount = ws_loan_amount * Decimal('0.0125') / 12
    elif ws_ltv_ratio > 90:
        ws_pmi_amount = ws_loan_amount * Decimal('0.0100') / 12
    elif ws_ltv_ratio > 85:
        ws_pmi_amount = ws_loan_amount * Decimal('0.0075') / 12
    else:
        ws_pmi_amount = ws_loan_amount * Decimal('0.0050') / 12
    return ws_pmi_amount

def evaluate_history_C7(ws_late_90_days: int, ws_late_60_days: int, ws_late_30_days: int, ws_risk_score: int) -> tuple[int, str, str, str]:
    """Evaluates history."""
    ws_factor_1: str = ""
    ws_factor_2: str = ""
    ws_factor_3: str = ""

    if ws_late_90_days > 0:
        ws_risk_score -= 50
        ws_factor_1 = 'SEVERE DELINQUENCY HISTORY'
    if ws_late_60_days > 2:
        ws_risk_score -= 30
        ws_factor_2 = '60+ DAY DELINQUENCIES'
    if ws_late_30_days > 5:
        ws_risk_score -= 20
        ws_factor_3 = 'MULTIPLE 30-DAY LATES'
    return ws_risk_score, ws_factor_1, ws_factor_2, ws_factor_3

def calculate_final_risk_C7(ws_risk_score_in: int) -> tuple[int, str]:
    """Calculates final risk."""
    ws_risk_score: int = ws_risk_score_in // 4
    ws_risk_category: str
    if ws_risk_score >= 80:
        ws_risk_category = 'LOW RISK'
    elif ws_risk_score >= 60:
        ws_risk_category = 'MODERATE'
    elif ws_risk_score >= 40:
        ws_risk_category = 'ELEVATED'
    else:
        ws_risk_category = 'HIGH RISK'
    return ws_risk_score, ws_risk_category

def determine_approval_C7(ws_credit_tier: str, ws_risk_category: str, ws_dti_ratio: int, ws_loan_amount: Decimal, ws_base_rate: Decimal) -> tuple[str, str, Decimal, Decimal]:
    """Determines approval."""
    ws_approval_status: str = ""
    ws_conditions: str = ""
    ws_approved_amount: Decimal = Decimal(0)
    ws_approved_rate: Decimal = Decimal(0)
    if ws_credit_tier == 'F':
        ws_approval_status = 'D'
        ws_conditions = 'CREDIT SCORE TOO LOW'
        return ws_approval_status, ws_conditions, ws_approved_amount, ws_approved_rate
    if ws_risk_category == 'HIGH RISK':
        ws_approval_status = 'D'
        ws_conditions = 'RISK ASSESSMENT FAILED'
        return ws_approval_status, ws_conditions, ws_approved_amount, ws_approved_rate
    if ws_dti_ratio > 50:
        ws_approval_status = 'D'
        ws_conditions = 'DTI RATIO TOO HIGH'
        return ws_approval_status, ws_conditions, ws_approved_amount, ws_approved_rate
    ws_approval_status = 'A'
    ws_approved_amount = ws_loan_amount
    ws_approved_rate = calculate_approved_terms_C7(ws_credit_tier, ws_base_rate, ws_risk_category)
    return ws_approval_status, ws_conditions, ws_approved_amount, ws_approved_rate

def calculate_approved_terms_C7(ws_credit_tier: str, ws_base_rate: Decimal, ws_risk_category: str) -> Decimal:
    """Calculates approved terms."""
    ws_approved_rate: Decimal = Decimal(0)
    if ws_credit_tier == 'A':
        ws_approved_rate = ws_base_rate + Decimal('0.00')
    elif ws_credit_tier == 'B':
        ws_approved_rate = ws_base_rate + Decimal('0.50')
    elif ws_credit_tier == 'C':
        ws_approved_rate = ws_base_rate + Decimal('1.50')
    elif ws_credit_tier == 'D':
        ws_approved_rate = ws_base_rate + Decimal('3.00')
    
    if ws_risk_category == 'ELEVATED':
        ws_approved_rate += Decimal('0.50')
    return ws_approved_rate

def generate_loan_terms_C7(ws_loan_amount: Decimal, ws_approved_rate: Decimal, ws_loan_term_months: int) -> tuple[Decimal, Decimal, Decimal]:
    """Generates loan terms."""
    ws_loan_interest_rate: Decimal = ws_approved_rate
    ws_monthly_rate: Decimal = ws_loan_interest_rate / 1200
    ws_compound_factor: Decimal = (1 + ws_monthly_rate) ** ws_loan_term_months
    ws_loan_monthly_pmt: Decimal = ws_loan_amount * ws_monthly_rate * ws_compound_factor / (ws_compound_factor - 1)
    ws_loan_principal_bal: Decimal = ws_loan_amount
    return ws_loan_interest_rate, ws_loan_monthly_pmt, ws_loan_principal_bal

def create_amortization_C7(ws_loan_amount: Decimal, ws_loan_term_months: int, ws_monthly_rate: Decimal, ws_loan_monthly_pmt: Decimal, ws_property_tax: Decimal, ws_insurance_premium: Decimal, ws_pmi_amount: Decimal, loan_mortgage: bool) -> tuple[List[Decimal], List[Decimal], List[Decimal], List[int], List[Decimal], List[Decimal], List[Decimal]]:
    """Creates amortization."""
    amort_interest: List[Decimal] = [Decimal(0)] * (ws_loan_term_months + 1)
    amort_principal: List[Decimal] = [Decimal(0)] * (ws_loan_term_months + 1)
    amort_balance: List[Decimal] = [Decimal(0)] * (ws_loan_term_months + 1)
    amort_payment_num: List[int] = [0] * (ws_loan_term_months + 1)
    amort_payment_amt: List[Decimal] = [Decimal(0)] * (ws_loan_term_months + 1)
    amort_escrow: List[Decimal] = [Decimal(0)] * (ws_loan_term_months + 1)
    amort_total_pmt: List[Decimal] = [Decimal(0)] * (ws_loan_term_months + 1)
    
    import datetime
    ws_running_balance: Decimal = ws_loan_amount
    ws_payment_date: datetime.date = datetime.date.today()
    ws_payment_month: int = ws_payment_date.month
    ws_payment_year: int = ws_payment_date.year
    
    for ws_amort_idx in range(1, ws_loan_term_months + 1):
        amort_interest[ws_amort_idx] = ws_running_balance * ws_monthly_rate
        amort_principal[ws_amort_idx] = ws_loan_monthly_pmt - amort_interest[ws_amort_idx]
        ws_running_balance -= amort_principal[ws_amort_idx]
        amort_balance[ws_amort_idx] = ws_running_balance
        amort_payment_num[ws_amort_idx] = ws_amort_idx
        amort_payment_amt[ws_amort_idx] = ws_loan_monthly_pmt
        
        if loan_mortgage:
            amort_escrow[ws_amort_idx] = (ws_property_tax + ws_insurance_premium) / 12
            amort_total_pmt[ws_amort_idx] = ws_loan_monthly_pmt + amort_escrow[ws_amort_idx] + ws_pmi_amount
        else:
            amort_total_pmt[ws_amort_idx] = ws_loan_monthly_pmt
        
        ws_payment_month += 1
        if ws_payment_month > 12:
            ws_payment_month = 1
            ws_payment_year += 1
        amort_payment_date: int
        amort_payment_date = ws_payment_year * 10000 + ws_payment_month * 100 + 1
    
    return amort_interest, amort_principal, amort_balance, amort_payment_num, amort_payment_amt, amort_escrow, amort_total_pmt

def finalize_loan_C7(ws_loan_term_months: int, ws_loan_id: str, ws_loan_type: str, ws_loan_amount: Decimal, ws_loan_interest_rate: Decimal, ws_loan_monthly_pmt: Decimal) -> None:
    """Finalizes loan."""
    import datetime
    ws_loan_start_date: datetime.date = datetime.date.today()
    ws_loan_end_date: datetime.date
    ws_loan_end_date = ws_loan_start_date + datetime.timedelta(days=(ws_loan_term_months * 30))
    ws_loan_status: str = 'A'
    create_loan_record_C7(ws_loan_id, ws_loan_type, ws_loan_amount, ws_loan_interest_rate, ws_loan_monthly_pmt, ws_loan_start_date, ws_loan_status)
    disburse_funds_C7(ws_loan_amount)
    send_confirmation_C7()

def create_loan_record_C7(ws_loan_id: str, ws_loan_type: str, ws_loan_amount: Decimal, ws_loan_interest_rate: Decimal, ws_loan_monthly_pmt: Decimal, ws_loan_start_date: str, ws_loan_status: str) -> None:
    """Creates loan record."""
    loan_rec_id: str = ws_loan_id
    loan_rec_type: str = ws_loan_type
    loan_rec_amount: Decimal = ws_loan_amount
    loan_rec_rate: Decimal = ws_loan_interest_rate
