    add_to_ytd_state_tax_C8(ws_state_tax)
    add_to_ytd_fica_C8(ws_fica_ss)
    add_to_ytd_fica_C8(ws_fica_medicare)
    add_to_ytd_net_C8(ws_net_pay)
    add_to_ytd_401k_C8(ws_401k_contrib)

