import decimal


@dataclass
class WsDailySummaryC10:
    """Represents daily summary data."""
    daily_date: Optional[str] = None
    daily_trans_count: int = 0
    daily_trans_amount: decimal.Decimal = decimal.Decimal("0.00")
    daily_deposits: decimal.Decimal = decimal.Decimal("0.00")
    daily_withdrawals: decimal.Decimal = decimal.Decimal("0.00")

@dataclass
class WsWeeklySummaryC10:
    """Represents weekly summary data."""
    weekly_week: int = 0
    weekly_trans_count: int = 0
    weekly_trans_amount: decimal.Decimal = decimal.Decimal("0.00")

@dataclass
class WsMonthlySummaryC10:
    """Represents monthly summary data."""
    monthly_month: int = 0
    monthly_year: int = 0
    monthly_trans_count: int = 0
    monthly_trans_amount: decimal.Decimal = decimal.Decimal("0.00")
    monthly_new_accounts: int = 0
    monthly_closed_accounts: int = 0

