def project_capital_needs_C14() -> None:
    """Projects capital needs."""
    ws_projected_rwa: Decimal = ws_risk_weighted_assets * (1 + ws_growth_rate)
    ws_required_capital: Decimal = ws_projected_rwa * ws_target_ratio / 100
    ws_capital_gap: Decimal = ws_required_capital - ws_total_capital

def identify_capital_actions_C14() -> None:
    """Identifies capital actions."""
    if ws_capital_gap > 0:
        if ws_capital_gap <= ws_retained_earnings_proj:
            ws_capital_action: str = 'ORGANIC GROWTH'
        elif ws_capital_gap <= ws_sub_debt_capacity:
            ws_capital_action: str = 'SUB DEBT ISSUANCE'
        else:
            ws_capital_action: str = 'EQUITY RAISE'
    else:
        ws_capital_action: str = 'NO ACTION NEEDED'

