def balance_gl_C14() -> None:
    """Balances the general ledger."""
    ws_total_assets: Decimal = Decimal("0")
    ws_total_liabilities: Decimal = Decimal("0")
    ws_total_equity: Decimal = Decimal("0")
    ws_eof_flag: str = 'N'
    while ws_eof_flag == 'N':
        # Assuming read_gl_master_file function exists and sets WS_EOF_FLAG
        ws_gl_record = read_gl_master_file_C14(gl_account=None)
        if ws_eof_flag == 'Y':
            pass
        else:
            if gl_asset:
                ws_total_assets += ws_gl_net_balance
            elif gl_liability:
                ws_total_liabilities += ws_gl_net_balance
            elif gl_equity:
                ws_total_equity += ws_gl_net_balance
    ws_eof_flag: str = 'N'
    ws_balance_check: Decimal = ws_total_assets - ws_total_liabilities - ws_total_equity
    if ws_balance_check != Decimal("0"):
        ws_error_msg: str = 'GL OUT OF BALANCE'
        handle_error_C14()

