def close_revenue_expense_C14() -> None:
    """Closes revenue and expense accounts."""
    ws_net_income: Decimal = Decimal("0")
    ws_eof_flag: str = 'N'
    while ws_eof_flag == 'N':
        ws_gl_record = read_gl_master_file_C14(gl_account=None)
        if ws_eof_flag == 'Y':
            pass
        else:
            if gl_revenue:
                ws_net_income += ws_gl_net_balance
                ws_gl_debit_balance: Decimal = Decimal("0")
                ws_gl_credit_balance: Decimal = Decimal("0")
                ws_gl_net_balance: Decimal = Decimal("0")
                rewrite_gl_record_C14(ws_gl_record)
            if gl_expense:
                ws_net_income -= ws_gl_net_balance
                ws_gl_debit_balance: Decimal = Decimal("0")
                ws_gl_credit_balance: Decimal = Decimal("0")
                ws_gl_net_balance: Decimal = Decimal("0")
                rewrite_gl_record_C14(ws_gl_record)
    ws_eof_flag: str = 'N'

