    ws_gl_record = read_gl_master_file_C14(ws_gl_account) #Key is gl_account
    ws_gl_credit_balance += ws_net_income
    ws_gl_net_balance: Decimal = ws_gl_credit_balance - ws_gl_debit_balance
    rewrite_gl_record_C14(ws_gl_record)

