    ws_ic_count = 0
    ws_eof_flag = 'N'
    while ws_eof_flag != 'Y':
        try:
            ws_ic_balance = read_intercompany_file()
            ws_ic_count += 1
            if ws_ic_count > len(ws_ic_array):
                ws_ic_array.append(ws_ic_balance)
            else:
                ws_ic_array[ws_ic_count - 1] = ws_ic_balance
        except EOFError:
            ws_eof_flag = 'Y'
    ws_eof_flag = 'N'

