def match_ic_pairs_37320_C15() -> None:
    """Matches intercompany pairs."""
    global ws_ic_count, ws_ic_idx
    ws_ic_idx = 1
    while ws_ic_idx <= ws_ic_count:
        find_ic_counterpart_37325_C15()
        ws_ic_idx += 1

def find_ic_counterpart_37325_C15() -> None:
    """Finds the counterpart for an intercompany balance."""
    global ws_search_from, ws_search_to, ws_ic_idx, ws_ic_idx2, ws_ic_count, ws_ic_diff
    ws_search_from = ic_from_entity[ws_ic_idx - 1]
    ws_search_to = ic_to_entity[ws_ic_idx - 1]
    ws_ic_idx2 = 1
    while ws_ic_idx2 <= ws_ic_count:
        if ic_from_entity[ws_ic_idx2 - 1] == ws_search_to:
            if ic_to_entity[ws_ic_idx2 - 1] == ws_search_from:
                ws_ic_diff = ic_amount[ws_ic_idx - 1] + ic_amount[ws_ic_idx2 - 1]
                if ws_ic_diff != 0:
                    log_ic_diff_37326_C15()
                break
        ws_ic_idx2 += 1

